document:
// The session catalog's store port.
//
// Hexagonal (owner): an HTTP adapter serves the approved Sessions API over the catalog
// core, and the core depends only on this port. The PostgreSQL adapter and the SQLite
// adapter implement it, and they must pass one shared conformance suite. Nothing
// transport-shaped crosses this boundary: no SQL, no HTTP shapes, no driver types. The
// HTTP adapter owns the approved wire shapes (amountMicros as a decimal string,
// nextPageToken, problem documents); this port speaks the domain values (bigint micros,
// epoch ms, opaque cursors).
//
// Idempotency — every write takes a Write: the reporting event's id and its position in
// the session's ordered write stream. The store holds a per-session watermark, the
// highest sequence applied, updated in the same transaction as the write it guards; a
// write at or below the watermark is a no-op that moves no row and no count. Spend and
// counts are deltas, so a replay provably changes nothing. The channel orders events per
// session, so the watermark is a sequence, not a set of ids. Delete and rebuild reset a
// session's watermark with its rows.
//
// Transactions — a lifecycle write applies the row and its derived counts (state,
// lastRun, cost, tokens, pendingAsks, oldestAskAt, lastActivity) in one atomic
// transaction: recordRunOutcome cancels the session's pending asks and sums the run's
// spend and tokens with the state and lastRun it writes; openAsk and resolveAsk move the
// ask and the session's counts together. A refused write changes nothing.
//
// Schema migration — the adapters own the schema: append-only migrations, never edited
// once released. The core calls migrate() at startup, memoizes success, and retries
// while the database is down, so the distributor can start before Postgres does. This
// port carries no schema knowledge.
//
// Rebuild — recovery replays each session's log through this same port: the core deletes
// the session's rows (deleteSession, which resets its watermark) and re-applies the
// session's recorded writes in order. The mapping from log events to these methods lives
// in the core, never in an adapter.
//
// Conformance — one shared suite runs against both adapters on one shared corpus and
// must prove: (1) every write lands exactly the row it documents, all counts included;
// (2) replaying any write is a no-op — every row and count unchanged; (3) the state
// machine applies, no-ops and refuses exactly as documented, and a refusal changes
// nothing; (4) recordRunOutcome is a single point of consistency — no torn row is
// ever visible; (5) lists — every orderBy, and a battery of ASTs covering every leaf
// kind and every field — return the same rows in the same order as the reference,
// paging to the end without gaps or duplicates, stable under interleaved writes, with
// the list's key as final tiebreak; (6) a cursor is bound to the (where, orderBy) that
// issued it — a changed query, order, or a token the adapter would not re-issue is
// refused; (7) bare terms and phrases full-text search the documented fields (sessions:
// title, key, lastMessage; asks: prompt question, tool name; artifacts: summary,
// outcome), with SQLite FTS5 and PostgreSQL tsvector agreeing on the corpus; (8) sums
// stay integers — an exact sum past 2^53 micros on both adapters; (9) deleting a
// session's rows and replaying its log through this port reproduces the live rows
// exactly.

/** A JSON value of any shape: the recursive set the catalog stores in open fields,
 * such as a resolved approval's tool arguments, which are kept as the audit trail.
 * Supplied by the session (the gated tool's arguments) and the judge; carried as-is and
 * serialized at the adapters' edge. */
export type Json = null | boolean | number | string | Json[] | { [field: string]: Json };

/** A money amount: an ISO 4217 currency code and its int64 count of millionths. The
 * port and the core carry the micros as bigint so sums stay exact past 2^53; only the
 * HTTP adapter encodes the approved wire shape (a decimal string), and the adapters
 * convert at their edge (SQLite INTEGER, PostgreSQL int8 or numeric). Unpriced spend is
 * 0n in the deployment's currency, never absent. */
export type Money = { currencyCode: string; micros: bigint };

/** The server-set actor: who made the decision. Supplied by the core from the request's
 * credential — never from a body — and served back on the resolution. A person the
 * reverse proxy authenticated (id present) or the tailnet itself (no id), mirroring the
 * Sessions API's Principal. */
export type Principal = { kind: 'person'; id: string } | { kind: 'tailnet' };

/** Token counts by kind, integer and non-negative. Supplied by the session on run end,
 * as the run's own delta; the store sums it into the session row's lifetime totals. */
export type TokenUsage = { input: number; output: number; cacheRead: number; cacheWrite: number };

/** The idempotency header every write takes: the reporting event's id (for a
 * person-driven write, the core's action id) and its position in the session's ordered
 * write stream, assigned by the core. The store compares seq against the session's
 * watermark inside the write's own transaction: at or below, the write is a no-op;
 * above, it applies and the watermark becomes seq. */
export type Write = { id: string; seq: number };

/** The session's lifecycle state. running: the process has an active run or waits on a
 * person. idle: the process is up with no active work. stopped: no process. archived:
 * hidden, and left only by invoking the session, which reactivates it (running). */
export type SessionState = 'running' | 'idle' | 'stopped' | 'archived';

/** How a run ended. */
export type RunOutcome = 'succeeded' | 'failed' | 'aborted';

/** One step of a run that ended failed, with its error text. Supplied by the session on
 * run end; served on the row's lastRun. */
export type FailedStep = { step: string; error: string };

/** One session's catalog row: what lists, Home and the session pages need. Written by
 * the core through this port; served by the HTTP adapter as the Sessions API's session.
 * Dates are epoch ms — the wire speaks RFC 3339 and the HTTP adapter converts. */
export type SessionRow = {
  /** The session key: the address of one agent's durable conversation. */
  key: string;
  /** The agent bound to the session. */
  agent: string;
  /** The session's title; absent when it has none beyond the default. */
  title?: string;
  state: SessionState;
  /** When the session was created. */
  createdAt: number;
  /** When the session last did work, written when a run ends. */
  lastActivity: number;
  /** The session's lifetime cost; the store sums run deltas in integer micros. */
  cost: Money;
  /** The session's lifetime token counts; the store sums run deltas. */
  tokens: TokenUsage;
  /** Asks still pending, approvals and questions alike; 0 when none. */
  pendingAsks: number;
  /** When the session's oldest pending ask was raised; present while pendingAsks > 0. */
  oldestAskAt?: number;
  /** The session's latest run; present once a run has ended. */
  lastRun?: { outcome: RunOutcome; endedAt: number; failedSteps: FailedStep[] };
  /** The text of the session's last message, present once a run has ended with one; a
   * full-text source of the session list only, never otherwise surfaced. */
  lastMessage?: string;
};

/** What kind of ask: a gated tool call awaiting approval, or a prompt to a person. */
export type AskType = 'approval' | 'question';

/** The ask's lifecycle: pending until answered, resolved by a person, or cancelled
 * when the run that raised it ends or aborts. */
export type AskState = 'pending' | 'resolved' | 'cancelled';

/** The prompt a question ask carries. Supplied by the session when it raises the ask;
 * kept on the row in every state. */
export type AskPrompt = {
  question: string;
  options: string[];
  /** A per-option description, keyed by the option's label. */
  optionDescriptions?: Record<string, string>;
  /** The suggested option's index into options. */
  suggested?: number | null;
  /** Whether a free-text answer was allowed. */
  freeText: boolean;
  evidence?: string | null;
  header?: string | null;
  title?: string | null;
  detail?: string | null;
};

/** One ask of a session: approvals and questions as one resource. Written by the core
 * through this port; served by the HTTP adapter as the Sessions API's ask. Dates are
 * epoch ms. A resolved approval keeps its tool arguments: the record of what was
 * approved is the audit trail. */
export type AskRow = {
  /** The session key the ask belongs to; carried by every row and queryable. */
  session: string;
  /** The ask's id within its session. */
  id: string;
  type: AskType;
  state: AskState;
  /** When the ask was raised. */
  createdAt: number;
  /** When the ask was resolved; present once resolved. */
  resolvedAt?: number;
  /** The answer; present once resolved. by is the server-set actor. */
  resolution?: { by: Principal; choice: string; text?: string; reason?: string };
  /** The gated tool call; present for type approval and kept after resolution. */
  toolCall?: { tool: string; args: Json };
  /** The prompt; present for type question. */
  prompt?: AskPrompt;
};

/** The judge's verdict on a sealed version. Supplied by the judge after the seal,
 * through updateArtifactVerdict; served on the artifact row and queryable as
 * verdict.passed. */
export type Verdict = {
  passed: boolean;
  /** The judge gave up before the version passed, having reached its revision limit. */
  limitReached?: boolean;
  gatesFailed?: string[];
  score?: number;
  checks?: Array<{
    criterion: string;
    id: string;
    label?: string;
    /** A weight, or 'gate' for a pass/fail gate. */
    weight: number | 'gate';
    /** The check's numeric reading, when it has one. */
    met: number | null;
    notes: string[];
    scope?: string;
  }>;
};

/** One sealed artifact version. Written by the core through this port — the seal, then
 * the judge's verdict and attached links — and served by the HTTP adapter as the
 * Sessions API's artifact. The row always carries the content: the per-session list
 * serves it in full and the cross-session list projects it away. Dates are epoch ms. */
export type ArtifactRow = {
  /** The session key the version belongs to; carried by every row and queryable. */
  session: string;
  kind: string;
  version: number;
  hash: string;
  content: string;
  /** When the version was sealed. */
  createdAt: number;
  /** The judge's verdict, present when the version was checked. */
  verdict?: Verdict | null;
  /** Pointers extensions attached to the version after the fact, e.g. where it was
   * delivered. */
  links?: Array<{ label: string; url: string }>;
  /** The kind's own one-word reading of the content, when it has one. */
  outcome?: string;
  /** A summary of the version's content. */
  summary?: string;
  /** What the version was written against, e.g. a review's head commit. */
  basis?: string;
  /** Set on a version that carried an earlier approval forward instead of being
   * judged: the sha it came from and that review's link. */
  carriedFrom?: { sha: string; url?: string };
};

/** The fields the session list's query may name: exactly the approved list's q field
 * set. Supplied by the core (the maintained Lucene parser, validated against this set
 * there, so an unknown field is a 400 that never reaches a store); consumed by the
 * adapters, which compile each to its own column. */
export type SessionField = 'key' | 'agent' | 'title' | 'state' | 'createdAt' | 'lastActivity' | 'cost.currencyCode' | 'cost.amountMicros' | 'tokens.input' | 'tokens.output' | 'tokens.cacheRead' | 'tokens.cacheWrite' | 'pendingAsks' | 'oldestAskAt' | 'lastRun.outcome';

/** The fields both ask lists' queries may name. The per-session list is the same
 * operation as the cross-session list with the session term folded in, so its field
 * set is this one with session; the store exposes the one set. */
export type AskField = 'session' | 'type' | 'state' | 'createdAt' | 'resolvedAt' | 'tool';

/** The fields both artifact lists' queries may name, likewise. */
export type ArtifactField = 'session' | 'kind' | 'version' | 'createdAt' | 'verdict.passed';

// The value a leaf carries, per field, one mapping per collection: strings for the
// text fields and currency code, enums for states and outcomes, bigint for the micros,
// epoch ms for the dates, and integer numbers for the counts.
type ValueOf<F extends string> =
  F extends SessionField
    ? F extends 'key' | 'agent' | 'title' | 'cost.currencyCode' ? string
    : F extends 'state' ? SessionState
    : F extends 'lastRun.outcome' ? RunOutcome
    : F extends 'cost.amountMicros' ? bigint
    : number
    : F extends AskField
    ? F extends 'session' | 'tool' ? string
    : F extends 'type' ? AskType
    : F extends 'state' ? AskState
    : number
    : F extends ArtifactField
    ? F extends 'session' | 'kind' ? string
    : F extends 'verdict.passed' ? boolean
    : number
    : never;

// The collection's full-text fields, where bare terms search: the documented text
// fields only.
type TextFieldsOf<F extends string> =
  F extends SessionField ? Extract<F, 'key' | 'agent' | 'title'>
  : F extends AskField ? Extract<F, 'session' | 'tool'>
  : F extends ArtifactField ? Extract<F, 'session' | 'kind'>
  : never;

// One fielded leaf, precise per field: the value type is ValueOf<F>, and prefix and
// wildcard leaves are unconstructible on any field the collection does not document as
// text.
type FieldLeaf<F extends string> =
  | { kind: 'match'; field: F; value: ValueOf<F> }
  | { kind: 'prefix'; field: F & TextFieldsOf<F>; value: string }
  | { kind: 'wildcard'; field: F & TextFieldsOf<F>; pattern: string }
  | { kind: 'compare'; field: F; op: 'gt' | 'gte' | 'lt' | 'le'; value: ValueOf<F> }
  | { kind: 'range'; field: F; from?: { value: ValueOf<F>; inclusive: boolean }; to?: { value: ValueOf<F>; inclusive: boolean } };

/** The parsed Lucene query of one list. The core parses q into this AST with a
 * maintained Lucene parser — never hand-rolled, and never in an adapter — and the
 * adapters compile it to their own SQL, full text included (SQLite FTS5, PostgreSQL
 * tsvector). A store never sees a field its collection lacks, because the core
 * validated it against the field set; an adapter that meets an unknown kind has a core
 * bug and must fail loudly, not guess. F is the collection's field set, and it fixes
 * each leaf's field type and value type. An absent or empty q is { kind: 'all' }. */
export type QueryAst<F extends string> =
  | { kind: 'all' }
  | { kind: 'and'; terms: QueryAst<F>[] }
  | { kind: 'or'; terms: QueryAst<F>[] }
  | { kind: 'not'; term: QueryAst<F> }
  /** A bare term or bare quoted phrase, no field: a full-text search over the
   * collection's documented text fields. phrase marks a quoted phrase; wildcard marks
   * a * or ? inside the term. */
  | { kind: 'text'; value: string; phrase?: boolean; wildcard?: boolean }
  | (F extends string ? FieldLeaf<F> : never);

/** The session list's allowed orders, each with its fixed direction: lastActivity
 * (the default, newest first), createdAt (newest first), oldestAskAt (oldest wait
 * first). The list's key is always the final tiebreak, so pages are a stable keyset,
 * and the choice is part of what a cursor is bound to. */
export type SessionOrder = 'lastActivity' | 'createdAt' | 'oldestAskAt';

/** The ask lists' allowed order: createdAt, newest first (the per-session list's
 * default) or oldest first (the cross-session list's default — the needs-you queue).
 * The ask's (session, id) is the final tiebreak. */
export type AskOrder = 'createdAt:newest' | 'createdAt:oldest';

/** The artifact lists' allowed order: createdAt, newest first. The artifact's
 * (session, kind, version) is the final tiebreak. */
export type ArtifactOrder = 'createdAt:newest';

/** One list request. where is the parsed query — { kind: 'all' } when q was absent or
 * empty; orderBy is the list's allowed order; pageSize is a positive integer (the core
 * caps it as the REST surface does); cursor is the opaque keyset cursor a previous page
 * returned, bound to the (where, orderBy) pair that issued it. Supplied by the core;
 * consumed by the adapters, which compile it to one page of their own SQL. */
export type ListOptions<F extends string, O extends string> = {
  where: QueryAst<F>;
  orderBy: O;
  pageSize: number;
  cursor?: string;
};

/** One keyset page. rows are in the requested order, the list's key the final
 * tiebreak; cursor is present while more rows remain after this page and is bound to
 * the (where, orderBy) pair that produced it. An adapter must refuse a cursor it would
 * not re-issue for that pair, and a core presenting a cursor under a changed query or
 * order is the 400 the REST surface answers. */
export type ListPage<T> = { rows: T[]; cursor?: string };

/** The session catalog's store port: the interface the catalog core depends on,
 * implemented by the PostgreSQL adapter and the SQLite adapter, which must pass one
 * shared conformance suite. The core supplies every argument — it parses q into
 * QueryAst, validates it against the collection's field set, orders writes per session,
 * caps pageSize, and maps each session's log events to these calls on rebuild; the
 * adapters supply only storage, and they compile the typed AST to their own SQL — they
 * never parse a query and never coerce a value.
 *
 * Idempotency: every write takes the reporting event's Write, and the store records a
 * per-session watermark — the highest sequence applied — in the same transaction as the
 * write, so a replay is a no-op that provably changes no row and no count.
 *
 * Transactions: a lifecycle write applies the row and its derived counts in one atomic
 * transaction, and a refused write changes nothing.
 *
 * Reads are pure: they read stored rows, create nothing, and never start a session's
 * process; an absent row is undefined, and a list answers a page. */
export interface SessionCatalogStore {
  /** Applies the store's schema migrations. The adapter owns the schema — append-only
   * migrations, never edited once released — and the core calls this at startup,
   * memoizes success, and retries while the database is down, so the distributor can
   * start before the store's database does. */
  migrate(): Promise<void>;

  /** Closes the store's connection to its database; the core calls it on shutdown. */
  close(): Promise<void>;

  // --- sessions ---

  /** Records a created session: the row starts stopped, with zero cost and tokens and
   * no pending asks. Replaying the create at or below the session's watermark is a
   * no-op. */
  createSession(write: Write, row: { key: string; agent: string; createdAt: number }): Promise<void>;

  /** Applies a lifecycle change driven by the session's lifecycle channel. `to` is
   * 'running' (a run starts, or invoking reactivates an archived session — the only way
   * out of archived), 'idle' (a run ends and the process is up) or 'stopped' (the
   * process stops). The table, checked and applied atomically in the write's own
   * transaction: to the target state is a no-op; 'idle' applies from running only;
   * 'stopped' applies from running or idle, not from archived; 'running' applies from
   * idle, stopped or archived. Returns whether the state moved and the session's state.
   */
  transitionSession(write: Write, change: { key: string; to: 'running' | 'idle' | 'stopped' }): Promise<{ applied: boolean; state?: SessionState }>;

  /** Renames the session (the person's title write). A null title restores the default.
   * Renaming to the current title is a no-op; the core 404s an absent key before
   * calling. */
  renameSession(write: Write, change: { key: string; title: string | null }): Promise<void>;

  /** Archives the session (the person's state:archived write). Applies from idle or
   * stopped; refused while the session is running or waits on a person — the REST
   * surface's 409 — and a no-op when it is already archived — the REST surface's 200
   * no-op. The check and the write are one atomic transaction. Returns whether the
   * state moved and the session's state. */
  archiveSession(write: Write, change: { key: string }): Promise<{ applied: boolean; state?: SessionState }>;

  /** Unarchives the session (the person's state:stopped write): archived back to
   * stopped. A no-op when the session is not archived. Returns whether the state moved
   * and the session's state. */
  unarchiveSession(write: Write, change: { key: string }): Promise<{ applied: boolean; state?: SessionState }>;

  /** Records a run's outcome and spend — the atomic heart of the catalog. In one
   * transaction the store cancels the session's pending asks (the run that raised them
   * has ended), zeroes pendingAsks and clears oldestAskAt, sums the run's spend and
   * tokens into the row's lifetime totals as integers, sets lastActivity to endedAt,
   * lastRun to the outcome and lastMessage when supplied, and moves the state to the
   * process's post-run state. A torn row is never visible. */
  recordRunOutcome(write: Write, outcome: {
    key: string;
    /** The process's post-run state: idle while it stays up, stopped while it goes
     * down. */
    state: 'idle' | 'stopped';
    outcome: RunOutcome;
    endedAt: number;
    failedSteps: FailedStep[];
    /** The run's spend delta; the store sums it into the row's lifetime cost. */
    spend: Money;
    /** The run's token delta; the store sums it into the row's lifetime totals. */
    tokens: TokenUsage;
    /** The text of the run's last message, when it has one. */
    lastMessage?: string;
  }): Promise<void>;

  /** Deletes the session's catalog rows — its session, asks and artifacts — and its
   * watermark, so a rebuild can replay the session's log through this same port.
   * Idempotent in effect: it answers whether the session had rows, and deleting the
   * same key again answers false — the REST surface's 404. The session's directory is
   * the driver's, not the store's. */
  deleteSession(write: Write, change: { key: string }): Promise<boolean>;

  /** Reads one session's row; undefined when the deployment knows no such key. Reads
   * create nothing and never start the session's process. */
  getSession(key: string): Promise<SessionRow | undefined>;

  /** One keyset page of the session list. This is the one list operation of the
   * collection; the core composes the per-session views from it — a session's asks is
   * listAsks with the session term folded into where. */
  listSessions(options: ListOptions<SessionField, SessionOrder>): Promise<ListPage<SessionRow>>;

  // --- asks ---

  /** Opens a pending ask — approvals and questions as one resource. In one
   * transaction the store records the ask, increments pendingAsks, and sets oldestAskAt
   * to the oldest pending ask's createdAt; a session that is not running becomes
   * running, because waiting on a person is running. */
  openAsk(write: Write, ask: {
    key: string;
    id: string;
    type: AskType;
    createdAt: number;
    /** The gated tool call; present for type approval. */
    toolCall?: { tool: string; args: Json };
    /** The prompt; present for type question. */
    prompt?: AskPrompt;
  }): Promise<void>;

  /** Resolves a pending ask: the person's answer. Applies only while the ask is
   * pending; in one transaction it sets the ask's state, resolvedAt and resolution —
   * by is the server-set actor, never a value the store invents — decrements
   * pendingAsks and recomputes oldestAskAt. Returns whether it applied and the ask's
   * row; the core 404s an absent ask and 409s a non-pending one. */
  resolveAsk(write: Write, change: {
    key: string;
    id: string;
    by: Principal;
    choice: string;
    text?: string;
    reason?: string;
    resolvedAt: number;
  }): Promise<{ applied: boolean; ask?: AskRow }>;

  /** Reads one ask of a session, in whatever state it has: pending, resolved or
   * cancelled; undefined when no such session or ask exists. */
  getAsk(key: string, id: string): Promise<AskRow | undefined>;

  /** One keyset page of asks — the one list operation of the collection. Every row
   * carries its session's key, so the per-session list is this operation with the
   * session term folded into where, and the cross-session list answers 'needs you'
   * (q=state:pending, oldest first) in one page. */
  listAsks(options: ListOptions<AskField, AskOrder>): Promise<ListPage<AskRow>>;

  // --- artifacts ---

  /** Records a sealed artifact version: the only write that creates an artifact row.
   * The judge's verdict and attached links arrive after the fact, through
   * updateArtifactVerdict and addArtifactLink. */
  sealArtifact(write: Write, artifact: {
    key: string;
    kind: string;
    version: number;
    hash: string;
    content: string;
    createdAt: number;
    /** The judge's verdict, present when the version was checked at the seal. */
    verdict?: Verdict | null;
    /** Pointers attached at the seal; more arrive through addArtifactLink. */
    links?: Array<{ label: string; url: string }>;
    outcome?: string;
    summary?: string;
    basis?: string;
    carriedFrom?: { sha: string; url?: string };
  }): Promise<void>;

  /** Attaches or replaces the judge's verdict on a sealed version — the write the REST
   * surface serves and filters on (verdict.passed). A no-op when the version is absent.
   */
  updateArtifactVerdict(write: Write, change: {
    key: string;
    kind: string;
    version: number;
    verdict: Verdict | null;
  }): Promise<void>;

  /** Attaches one pointer to a sealed version after the fact, e.g. where it was
   * delivered. A no-op when the version is absent. */
  addArtifactLink(write: Write, change: {
    key: string;
    kind: string;
    version: number;
    link: { label: string; url: string };
  }): Promise<void>;

  /** One keyset page of sealed artifact versions, content included — the one list
   * operation of the collection; the REST surface serves the per-session list in full
   * and projects the content away on the cross-session list. */
  listArtifacts(options: ListOptions<ArtifactField, ArtifactOrder>): Promise<ListPage<ArtifactRow>>;
}
